INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0001','Это моя семья.','Э́то моя́ семья́.','Esta é a minha família.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0002','Мой отец врач.','Мой оте́ц врач.','Meu pai é médico.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0003','Моя мама работает в школе.','Моя́ ма́ма рабо́тает в шко́ле.','Minha mãe trabalha numa escola.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0004','Мой брат студент.','Мой брат студе́нт.','Meu irmão é estudante.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0005','Моя сестра любит музыку.','Моя́ сестра́ лю́бит му́зыку.','Minha irmã gosta de música.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0006','Мы живём в городе.','Мы живём в го́роде.','Moramos numa cidade.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0007','Мой дом большой.','Мой дом большо́й.','Minha casa é grande.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0008','Я люблю мою семью.','Я люблю́ мою́ семью́.','Eu amo a minha família.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0009','Утром я пью чай.','У́тром я пью чай.','De manhã eu bebo chá.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0010','Брат пьёт воду.','Брат пьёт во́ду.','Meu irmão bebe água.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0011','Мама готовит суп.','Ма́ма гото́вит суп.','A mãe prepara a sopa.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0012','Потом мы едим хлеб.','Пото́м мы еди́м хлеб.','Depois comemos pão.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0013','Я читаю книгу.','Я чита́ю кни́гу.','Eu leio um livro.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0014','Потом я иду в школу.','Пото́м я иду́ в шко́лу.','Depois eu vou para a escola.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0015','В городе большой парк.','В го́роде большо́й парк.','Na cidade há um grande parque.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0016','Там красивый музей.','Там краси́вый музе́й.','Lá há um museu bonito.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0017','Я иду в магазин.','Я иду́ в магази́н.','Eu vou à loja.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0018','В магазине я покупаю хлеб и молоко.','В магази́не я покупа́ю хлеб и молоко́.','Na loja eu compro pão e leite.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0019','Потом мы идём в парк.','Пото́м мы идём в парк.','Depois vamos ao parque.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0020','В парке много людей.','В па́рке мно́го люде́й.','No parque há muita gente.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0021','Это хороший день.','Э́то хоро́ший день.','É um bom dia.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0022','Сегодня хорошая погода.','Сего́дня хоро́шая пого́да.','Hoje o tempo está bom.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0023','Утром холодно.','У́тром хо́лодно.','De manhã está frio.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0024','Зимой идёт снег.','Зимо́й идёт снег.','No inverno cai neve.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0025','Весной тепло.','Весно́й тепло́.','Na primavera está quente.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0026','Летом я люблю гулять в парке.','Ле́том я люблю́ гуля́ть в па́рке.','No verão eu gosto de passear no parque.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0027','Осенью идёт дождь.','О́сенью идёт дождь.','No outono chove.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0028','Я не люблю холодную погоду.','Я не люблю́ холо́дную пого́ду.','Eu não gosto de tempo frio.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0029','Мы в ресторане.','Мы в рестора́не.','Estamos no restaurante.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0030','Вот стол.','Вот стол.','Aqui está a mesa.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0031','Я хочу суп и салат.','Я хочу́ суп и сала́т.','Eu quero sopa e salada.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0032','Мой друг хочет рыбу и вино.','Мой друг хо́чет ры́бу и вино́.','Meu amigo quer peixe e vinho.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0033','Вино хорошее.','Вино́ хоро́шее.','O vinho é bom.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0034','Рыба вкусная.','Ры́ба вку́сная.','O peixe é gostoso.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0035','Спасибо! Всё очень вкусно.','Спаси́бо! Всё о́чень вку́сно.','Obrigado! Está tudo muito gostoso.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0036','Мой дом маленький, но тёплый.','Мой дом ма́ленький, но тёплый.','Minha casa é pequena, mas aconchegante.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0037','В комнате стол и окно.','В ко́мнате стол и окно́.','No quarto há uma mesa e uma janela.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0038','Окно большое.','Окно́ большо́е.','A janela é grande.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0039','На столе книга и телефон.','На столе́ кни́га и телефо́н.','Sobre a mesa há um livro e um telefone.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0040','Мой брат сидит в комнате.','Мой брат сиди́т в ко́мнате.','Meu irmão está sentado no quarto.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0041','Он читает книгу.','Он чита́ет кни́гу.','Ele lê um livro.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0042','Я работаю на кухне.','Я рабо́таю на ку́хне.','Eu trabalho na cozinha.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0043','Мой папа работает в банке.','Мой па́па рабо́тает в ба́нке.','Meu pai trabalha num banco.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0044','Он директор.','Он дире́ктор.','Ele é diretor.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0045','Утром он идёт на работу.','У́тром он идёт на рабо́ту.','De manhã ele vai ao trabalho.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0046','Вечером он отдыхает.','Ве́чером он отдыха́ет.','À noite ele descansa.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0047','Моя мама врач.','Моя́ ма́ма врач.','Minha mãe é médica.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0048','Она работает в больнице.','Она́ рабо́тает в больни́це.','Ela trabalha num hospital.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0049','Это мой друг.','Э́то мой друг.','Este é o meu amigo.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0050','Он хороший человек.','Он хоро́ший челове́к.','Ele é uma boa pessoa.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0051','Он любит кино.','Он лю́бит кино́.','Ele gosta de cinema.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0052','Мы идём в кино.','Мы идём в кино́.','Vamos ao cinema.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0053','Потом мы идём в ресторан.','Пото́м мы идём в рестора́н.','Depois vamos ao restaurante.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0054','Мы любим этот ресторан.','Мы лю́бим э́тот рестора́н.','Nós gostamos deste restaurante.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0055','Кто это?','Кто э́то?','Quem é?','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0056','Это мой брат.','Э́то мой брат.','É o meu irmão.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0057','Что он делает?','Что он де́лает?','O que ele está fazendo?','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0058','Он читает.','Он чита́ет.','Ele está lendo.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0059','Где он работает?','Где он рабо́тает?','Onde ele trabalha?','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0060','Он работает в школе.','Он рабо́тает в шко́ле.','Ele trabalha numa escola.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0061','Почему ты не спишь?','Почему́ ты не спишь?','Por que você não dorme?','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0062','Я не сплю.','Я не сплю.','Eu não estou dormindo.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0063','Сегодня хороший день.','Сего́дня хоро́ший день.','Hoje é um bom dia.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0064','Завтра я иду в школу.','За́втра я иду́ в шко́лу.','Amanhã eu vou à escola.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0065','Вчера был дождь.','Вчера́ был дождь.','Ontem choveu.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0066','Сейчас вечер.','Сейча́с ве́чер.','Agora é fim de tarde.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0067','Уже ночь.','Уже́ ночь.','Já é noite.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0068','Я хочу спать.','Я хочу́ спать.','Eu quero dormir.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0069','Я хочу купить подарок.','Я хочу́ купи́ть пода́рок.','Eu quero comprar um presente.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0070','Подарок для мамы.','Пода́рок для ма́мы.','O presente é para a mamãe.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0071','Мама любит книги.','Ма́ма лю́бит кни́ги.','A mamãe gosta de livros.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0072','Это очень дорого.','Э́то о́чень до́рого.','Isso é muito caro.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0073','Я иду в магазин.','Я иду́ в магази́н.','Eu vou à loja.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0074','Это собака.','Э́то соба́ка.','Isto é um cachorro.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0075','Собака большая.','Соба́ка больша́я.','O cachorro é grande.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0076','Кошка маленькая.','Ко́шка ма́ленькая.','A gata é pequena.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0077','Я люблю собаку и кошку.','Я люблю́ соба́ку и ко́шку.','Eu gosto do cachorro e da gata.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0078','Собака спит.','Соба́ка спит.','O cachorro dorme.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0079','Кошка пьёт воду.','Ко́шка пьёт во́ду.','A gata bebe água.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0080','Птица красивая.','Пти́ца краси́вая.','O pássaro é bonito.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0081','Я учу русский язык.','Я учу́ ру́сский язы́к.','Eu estudo russo.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0082','Русский язык трудный.','Ру́сский язы́к тру́дный.','O russo é difícil.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0083','Я читаю и пишу.','Я чита́ю и пишу́.','Eu leio e escrevo.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0084','Мой учитель добрый.','Мой учи́тель до́брый.','Meu professor é bondoso.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0085','Он хорошо знает русский язык.','Он хорошо́ зна́ет ру́сский язы́к.','Ele conhece bem a língua russa.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0086','Вечером мы смотрим фильм.','Ве́чером мы смо́трим фильм.','À noite assistimos a um filme.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0087','Фильм интересный.','Фильм интере́сный.','O filme é interessante.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0088','Мама готовит ужин.','Ма́ма гото́вит у́жин.','A mamãe prepara o jantar.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0089','Уже ночь, и я хочу спать.','Уже́ ночь, и я хочу́ спать.','Já é noite, e eu quero dormir.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0090','Потом я иду спать.','Пото́м я иду́ спать.','Depois eu vou dormir.','autoral');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0091','Что это?','Что э́то?','O que é isto?','tatoeba:5412');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0092','Это интересно.','Э́то интере́сно.','Isto é interessante.','tatoeba:5513');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0093','Я могу только ждать.','Я могу́ то́лько ждать.','Eu só posso esperar.','tatoeba:5566');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0094','Я уже не знаю, что делать.','Я уже́ не зна́ю, что де́лать.','Já não sei o que fazer.','tatoeba:5576');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0095','Это игра слов.','Э́то игра́ слов.','Isto é um jogo de palavras.','tatoeba:5613');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0096','Зима — моё любимое время года.','Зима́ — моё люби́мое вре́мя го́да.','O inverno é a minha estação favorita.','tatoeba:5660');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0097','Доброе утро!','До́брое у́тро!','Bom dia!','tatoeba:329715');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0098','Я не понимаю.','Я не понима́ю.','Eu não entendo.','tatoeba:338488');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0099','Хороший вопрос.','Хоро́ший вопро́с.','Boa pergunta','tatoeba:338490');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0100','Я не люблю яблоки.','Я не люблю́ я́блоки.','Eu não gosto de maçãs.','tatoeba:351431');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0101','Кошка пьёт молоко.','Ко́шка пьёт молоко́.','O gato bebe leite.','tatoeba:351800');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0102','Я не знаю, что это.','Я не зна́ю, что э́то.','Eu não sei o que é isso.','tatoeba:366844');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0103','Я люблю ходить в кино.','Я люблю́ ходи́ть в кино́.','Gosto de ir ao cinema.','tatoeba:374368');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0104','Спасибо!','Спаси́бо!','Obrigado!','tatoeba:374869');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0105','Читал он очень много.','Чита́л он о́чень мно́го.','Ele lia muito.','tatoeba:376125');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0106','Пожалуйста.','Пожа́луйста.','De nada.','tatoeba:379409');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0107','Моего языка нет в списке!','Моего́ языка́ нет в спи́ске!','O meu idioma não está na lista!','tatoeba:389260');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0108','Я знаю, что она красивая.','Я зна́ю, что она́ краси́вая.','Eu sei que ela é bonita.','tatoeba:389742');
