INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0111','Пошли.','Пошли́.','Vamos.','tatoeba:397582');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0112','Это тоже яблоко.','Э́то то́же я́блоко.','Essa é uma maçã também.','tatoeba:400896');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0113','Большое спасибо!','Большо́е спаси́бо!','Muito obrigado!','tatoeba:401105');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0114','Он ест яблоко.','Он ест я́блоко.','Ele está comendo uma maçã.','tatoeba:405812');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0115','Мир и любовь.','Мир и любо́вь.','Paz e amor.','tatoeba:407469');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0116','Почему я?','Почему́ я?','Por que eu?','tatoeba:408110');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0117','Я иду в банк.','Я иду́ в банк.','Estou indo ao banco.','tatoeba:408696');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0118','Я живу в городе.','Я живу́ в го́роде.','Moro na cidade.','tatoeba:411304');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0119','Я не знаю.','Я не зна́ю.','Não sei.','tatoeba:414650');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0120','Это для моего друга.','Э́то для моего́ дру́га.','É para um amigo meu.','tatoeba:414902');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0121','Он пишет книги.','Он пи́шет кни́ги.','Ele escreve livros.','tatoeba:415892');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0122','Я не помню, где купил это.','Я не по́мню, где купи́л э́то.','Não me lembro onde o comprei.','tatoeba:416651');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0123','Привет, Том.','Приве́т, Том.','Olá, Tom.','tatoeba:417113');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0124','Что я могу сделать?','Что я могу́ сде́лать?','O que posso fazer?','tatoeba:417295');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0125','Я учусь.','Я учу́сь.','Eu estudo.','tatoeba:419766');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0126','Вчера шёл дождь.','Вчера́ шёл дождь.','Ontem choveu.','tatoeba:423125');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0127','Моя мать говорит медленно.','Моя́ мать говори́т ме́дленно.','Minha mãe fala devagar.','tatoeba:424548');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0128','Мать каждый день ходит на рынок.','Мать ка́ждый день хо́дит на ры́нок.','A mãe vai todos os dias ao mercado.','tatoeba:424599');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0129','Я не знаю, что сказать.','Я не зна́ю, что сказа́ть.','Eu não sei o que dizer.','tatoeba:426556');
INSERT INTO sentence(id,ru,ru_stress,pt,source) VALUES('s0130','Сделать хорошую шутку не всегда просто.','Сде́лать хоро́шую шу́тку не всегда́ про́сто.','Nem sempre é fácil contar uma boa piada.','tatoeba:428413');
